    h = int(g.get("grid_height", g.get("height", 0)) or 0)

    def pos(v, d=(0, 0)):
        if isinstance(v, dict):
            for k in ("position", "pos", "loc", "xy"):
                if k in v:
                    v = v[k]
                    break
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return d
        return d

