    best = (0, 0)
    bestv = -10**9
    for dx, dy in moves:
        nx, ny = me[0] + dx, me[1] + dy
        if nx < 0 or ny < 0 or nx >= w or ny >= h or (nx, ny) in blocked:
            continue
        score = 0
        if res:
            d = min(abs(nx - x) + abs(ny - y) for x, y in res)
            score -= d * 10
            if (nx, ny) in res:
                score += 50
        else:
            score += 1
        score -= abs(nx - op[0]) + abs(ny - op[1])
        if g.get("scores"):
            s = g["scores"]
            if isinstance(s, (list, tuple)) and len(s) >= 2 and s[0] < s[1]:
                score += (w + h) - (abs(nx - op[0]) + abs(ny - op[1]))
        if score > bestv or (score == bestv and (dx, dy) < best):
            bestv = score
            best = (dx, dy)
    return [int(best[0]), int(best[1])]

